update public.missions
set
  description = 'Meccanismi semplici come trasformatori di forza, corsa e vantaggio meccanico.',
  estimated_minutes = 13,
  xp_reward = 85,
  steps = '[
    {"type":"lesson","emoji":"⚙️","title":"Un Meccanismo Scambia Forza con Spostamento","content":"Leve, pulegge, viti e piani inclinati non regalano energia: redistribuiscono forza, corsa, velocita e accessibilita. Il loro valore emerge quando leggi il percorso del carico e capisci dove vuoi vantaggio meccanico e dove accetti piu corsa o piu attrito.","key_points":["Il vantaggio meccanico nasce da geometria e cinematica","Forza e spostamento si scambiano","Il meccanismo va letto sul lavoro richiesto"],"references":[{"title":"Simple machines and mechanics","url":"https://www.youtube.com/results?search_query=simple+machines+mechanics","type":"video","source":"YouTube"}],"visuals":[{"kind":"free-body","title":"Scambio forza-corsa","caption":"Il meccanismo cambia quanto sforzo serve e quanta corsa devi generare."}]},
    {"type":"fill-blank","emoji":"🧠","sentence":"Un vantaggio meccanico elevato riduce la forza richiesta ma in genere aumenta la ___.","options":["corsa necessaria","massa del pianeta","temperatura del browser","precisione infinita"],"correct":0,"explanation":"Se riduci la forza con il meccanismo, normalmente paghi in spostamento o velocita."},
    {"type":"challenge","title":"Attuatore Debole, Corsa Lunga","scenario":"Hai un attuatore piccolo che non genera molta forza, ma puoi concederti una corsa lunga nel sistema.","question":"Qual e la lettura piu forte?","options":["Serve piu tensione e basta","Un meccanismo con vantaggio meccanico puo convertire corsa in forza utile","I meccanismi non cambiano nulla","Conta solo la rigidezza del telaio"],"correct":1,"explanation":"Una leva o trasmissione corretta puo trasformare corsa disponibile in forza sul carico."},
    {"type":"sorting","title":"Scegliere un Meccanismo","emoji":"🗺️","question":"Ordina i passaggi piu maturi per scegliere un meccanismo semplice.","items":["Capire forza, corsa e vincoli del carico","Stimare quale trasformazione meccanica serve","Valutare attrito, gioco e ingombro","Chiudere il compromesso tra efficienza, controllo e producibilita"],"explanation":"Prima chiarisci il problema meccanico, poi la trasformazione, poi le perdite e infine il compromesso complessivo."},
    {"type":"design","title":"Design Review: Leva o Vite","brief":"Devi comprimere un elemento con poca forza attuabile ma con spazio limitato e richiesta di buona controllabilita.","constraints":["Forza attuatore limitata","Ingombro contenuto","Usura e attrito contano","La soluzione deve essere producibile"],"question":"Qual e la postura piu matura?","options":["Scegliere il meccanismo piu familiare","Leggere il tradeoff tra vantaggio meccanico, corsa, attrito e precisione del sistema","Aumentare il carico di progetto a caso","Ignorare il gioco"],"correct":1,"explanation":"Il meccanismo giusto si sceglie chiudendo forza, corsa, perdite e controllabilita.","tradeoffs":["Piu vantaggio meccanico spesso significa piu corsa","Attrito e gioco possono distruggere il controllo","Una soluzione semplice da fabbricare vale piu di una elegante ma fragile"],"references":[{"title":"Mechanical advantage basics","url":"https://www.youtube.com/results?search_query=mechanical+advantage+basics","type":"video","source":"YouTube"}]}
  ]'::jsonb
where title = 'Meccanismi e Macchine Semplici'
  and path_id = (select id from public.learning_paths where slug = 'mechanical-thinking');

update public.missions
set
  description = 'Fluidi come bilancio tra pressione, velocita e perdite lungo un percorso reale.',
  estimated_minutes = 13,
  xp_reward = 85,
  steps = '[
    {"type":"lesson","emoji":"🌊","title":"Un Fluido Trasporta Energia e Perde Margine","content":"Nei flussi reali contano pressione, velocita, sezione e perdite. Una linea, un ugello o un condotto non sono solo tubi: sono architetture che convertono energia di pressione in moto e dissipano parte del margine disponibile.","key_points":["Pressione e velocita si scambiano","Le perdite crescono lungo il percorso reale","Geometria e regime contano"],"formulas":[{"label":"Continuity","expression":"Q = A v","note":"Portata come area per velocita media."}],"references":[{"title":"Fluid dynamics basics","url":"https://www.youtube.com/results?search_query=fluid+dynamics+basics","type":"video","source":"YouTube"}],"visuals":[{"kind":"free-body","title":"Condotto e perdita","caption":"Il fluido accelera o perde margine a seconda della geometria del percorso."}]},
    {"type":"fill-blank","emoji":"💧","sentence":"Se la stessa portata passa in una sezione piu piccola, la velocita tende ad ___.","options":["aumentare","annullarsi","restare sempre uguale","diventare negativa per forza"],"correct":0,"explanation":"Dalla continuita, a parita di portata una sezione minore richiede velocita maggiore."},
    {"type":"challenge","title":"Linea che Perde Prestazione","scenario":"Una linea di fluido con molte curve e restringimenti non riesce piu a fornire la portata attesa al carico.","question":"Qual e la lettura piu forte?","options":["Conta solo la pompa","Le perdite distribuite e locali stanno erodendo il margine del sistema","La temperatura del logo e sbagliata","La sezione non conta"],"correct":1,"explanation":"Curve, restringimenti e attrito interno possono ridurre drasticamente la prestazione utile del circuito fluido."},
    {"type":"sorting","title":"Leggere un Percorso di Flusso","emoji":"🧭","question":"Ordina i passaggi piu maturi per leggere un problema di flusso.","items":["Capire portata richiesta e geometria del percorso","Stimare dove pressione e velocita cambiano","Valutare perdite e colli di bottiglia","Chiudere il margine di funzionamento del sistema"],"explanation":"Prima funzione e percorso, poi conversione, poi perdite e infine margine operativo."},
    {"type":"design","title":"Design Review: Condotto Compatto","brief":"Devi portare fluido a un attuatore in poco spazio senza perdere troppa pressione lungo il percorso.","constraints":["Spazio ridotto","Portata minima da garantire","Curve obbligate","Affidabilita richiesta"],"question":"Qual e la postura piu matura?","options":["Aumentare solo la pompa","Valutare insieme geometria, sezione, perdite locali e margine di pressione","Ignorare il layout del percorso","Ridurre sezione ovunque per semplificare"],"correct":1,"explanation":"Il circuito fluido si chiude su geometria, perdite e margine utile, non solo sulla sorgente.","tradeoffs":["Piu sezione riduce perdite ma costa spazio","Un percorso pulito puo valere piu di una pompa piu grande","Il margine va letto al carico finale"],"references":[{"title":"Bernoulli and pipe losses","url":"https://www.youtube.com/results?search_query=bernoulli+pipe+losses","type":"video","source":"YouTube"}]}
  ]'::jsonb
where title = 'Basi di Fluidodinamica'
  and path_id = (select id from public.learning_paths where slug = 'mechanical-thinking');

update public.missions
set
  description = 'Calore come flusso guidato da gradienti, resistenze termiche e limiti di dissipazione.',
  estimated_minutes = 13,
  xp_reward = 85,
  steps = '[
    {"type":"lesson","emoji":"🔥","title":"Il Calore Si Propaga Lungo un Percorso di Resistenze","content":"La trasmissione del calore si legge come un circuito: una sorgente termica, un percorso di conduzione, eventuale convezione verso l ambiente e un margine massimo di temperatura accettabile. Materiale, area e differenza di temperatura chiudono il problema.","key_points":["Il calore segue gradienti di temperatura","Materiali e superfici introducono resistenze termiche","La dissipazione e un vincolo di sistema"],"references":[{"title":"Heat transfer basics","url":"https://www.youtube.com/results?search_query=heat+transfer+basics","type":"video","source":"YouTube"}],"visuals":[{"kind":"free-body","title":"Percorso termico","caption":"La sorgente scalda, il corpo conduce, l ambiente assorbe solo se il percorso termico lo permette."}]},
    {"type":"fill-blank","emoji":"🌡️","sentence":"Se la resistenza termica del percorso cresce, a parita di potenza dissipata la temperatura tende ad ___.","options":["aumentare","sparire","restare identica","oscillare casualmente"],"correct":0,"explanation":"Piu resistenza termica significa maggiore salto di temperatura per smaltire la stessa potenza."},
    {"type":"challenge","title":"Driver che Va in Protezione","scenario":"Un modulo di potenza funziona bene a banco ma in involucro chiuso entra presto in protezione termica.","question":"Qual e la lettura piu forte?","options":["Il firmware e sempre il problema","Il percorso di dissipazione verso l ambiente e insufficiente","Conta solo il voltaggio di ingresso","Il componente e per forza guasto"],"correct":1,"explanation":"In enclosure reali la catena termica puo diventare il vero collo di bottiglia del sistema."},
    {"type":"sorting","title":"Chiudere un Bilancio Termico","emoji":"🧠","question":"Ordina i passaggi piu maturi per leggere un problema termico.","items":["Capire quanta potenza viene dissipata","Mappare il percorso termico dal componente all ambiente","Stimare resistenze termiche e margine di temperatura","Chiudere il compromesso tra raffreddamento, massa e ingombro"],"explanation":"Prima sorgente termica, poi percorso, poi margine e infine soluzione pratica."},
    {"type":"design","title":"Design Review: Dissipazione in Volume Chiuso","brief":"Devi far lavorare un elettronica di potenza in un volume compatto senza ventole e con temperatura ambiente variabile.","constraints":["Niente raffreddamento attivo","Temperatura ambiente non ideale","Massa limitata","Affidabilita richiesta"],"question":"Qual e la postura piu matura?","options":["Sperare che il case faccia il lavoro","Leggere il problema come rete termica tra sorgente, interfaccia, struttura e ambiente","Aumentare la frequenza di switching","Ignorare il duty cycle"],"correct":1,"explanation":"La dissipazione non si improvvisa: va chiusa sul percorso termico completo.","tradeoffs":["Piu massa termica aiuta il transitorio ma non sempre il regime","Piastre e interfacce migliorano la conduzione ma costano spazio","Il margine cambia con ambiente e duty cycle"],"references":[{"title":"Thermal design basics","url":"https://www.youtube.com/results?search_query=thermal+design+basics","type":"video","source":"YouTube"}]}
  ]'::jsonb
where title = 'Trasmissione del Calore'
  and path_id = (select id from public.learning_paths where slug = 'mechanical-thinking');

update public.missions
set
  description = 'Analisi strutturale come lettura di percorso di carico, rigidezza e concentrazione di sforzo.',
  estimated_minutes = 13,
  xp_reward = 85,
  steps = '[
    {"type":"lesson","emoji":"🏗️","title":"Una Struttura Va Letta Dove Passa il Carico","content":"L analisi strutturale parte sempre da una domanda: dove entra il carico, attraverso quali percorsi scorre e dove si concentra? Rigidezza globale e sforzo locale non sono la stessa cosa. Un pezzo puo sembrare robusto ma fallire in una zona piccola e critica.","key_points":["Il percorso di carico guida la lettura strutturale","Rigidezza globale e picchi locali sono diversi","I dettagli geometrici possono dominare il failure"],"references":[{"title":"Structural analysis basics","url":"https://www.youtube.com/results?search_query=structural+analysis+basics","type":"video","source":"YouTube"}],"visuals":[{"kind":"free-body","title":"Load path first","caption":"Prima carico e vincoli, poi dettagli geometrici e margine."}]},
    {"type":"fill-blank","emoji":"📎","sentence":"Una concentrazione di sforzo nasce spesso vicino a un cambio di geometria o a un ___.","options":["vincolo","colore del pezzo","nome del CAD","commento del team"],"correct":0,"explanation":"Fori, raccordi scarsi e vincoli rigidi sono luoghi tipici di concentrazione."},
    {"type":"challenge","title":"Telaio Pesante ma Debole","scenario":"Un supporto e stato ispessito quasi ovunque, ma continua a mostrare cricche nello stesso punto vicino a un foro di fissaggio.","question":"Qual e la lettura piu forte?","options":["Serve ancora piu materiale ovunque","La concentrazione locale domina piu della massa totale aggiunta","Conta solo il materiale base","Il problema e solo dinamico"],"correct":1,"explanation":"Se il failure nasce in un hotspot, aggiungere massa lontano da li serve poco."},
    {"type":"sorting","title":"Leggere una Struttura","emoji":"🧭","question":"Ordina i passaggi piu maturi per una prima analisi strutturale.","items":["Definire carichi, vincoli e casi di uso","Ricostruire il percorso di carico nella geometria","Individuare punti di concentrazione e deformazione critica","Chiudere il margine rispetto a fatigue, producibilita e massa"],"explanation":"Prima il caso di carico, poi il percorso, poi hotspot e infine il margine ingegneristico."},
    {"type":"design","title":"Design Review: Staffa Leggera","brief":"Devi alleggerire una staffa mantenendo margine strutturale e buona producibilita.","constraints":["Massa da ridurre","Picchi di carico presenti","Punti di fissaggio obbligati","Produzione ripetibile"],"question":"Qual e la postura piu matura?","options":["Togliere materiale dove capita","Leggere percorso di carico e concentrazioni prima di modificare la geometria","Aumentare il materiale dei bulloni e basta","Ignorare i casi di picco"],"correct":1,"explanation":"Un alleggerimento forte nasce da una lettura strutturale pulita, non da tagli casuali.","tradeoffs":["Meno massa puo significare meno rigidezza","Raccordi e transizioni buone riducono hotspot","La geometria deve restare fabbricabile"],"references":[{"title":"Stress concentration fundamentals","url":"https://www.youtube.com/results?search_query=stress+concentration+fundamentals","type":"video","source":"YouTube"}]}
  ]'::jsonb
where title = 'Basi di Analisi Strutturale'
  and path_id = (select id from public.learning_paths where slug = 'mechanical-thinking');

update public.missions
set
  description = 'Termodinamica come bilancio di energia, trasformazioni e limiti reali di efficienza.',
  estimated_minutes = 13,
  xp_reward = 85,
  steps = '[
    {"type":"lesson","emoji":"♨️","title":"La Termodinamica Chiude Bilanci, Non Slogan","content":"La termodinamica ti chiede dove entra energia, dove viene accumulata, dove esce e quali trasformazioni sono realmente possibili. Efficienza, calore e lavoro sono legati da limiti fisici, non solo da scelta progettuale.","key_points":["Energia si conserva ma cambia forma","Calore e lavoro non sono equivalenti dal punto di vista del controllo","L efficienza ha limiti fisici"],"references":[{"title":"Thermodynamics introduction","url":"https://www.youtube.com/results?search_query=thermodynamics+introduction","type":"video","source":"YouTube"}],"visuals":[{"kind":"free-body","title":"Bilancio energetico","caption":"Ogni sistema termico va letto su ingressi, uscite, accumulo e perdite."}]},
    {"type":"fill-blank","emoji":"📦","sentence":"In un bilancio energetico, se entra piu energia di quanta ne esca, il sistema tende ad ___.","options":["accumulare energia","annullarsi","diventare perfetto","ignorare le perdite"],"correct":0,"explanation":"La differenza tra ingresso e uscita finisce in accumulo o variazione di stato del sistema."},
    {"type":"challenge","title":"Macchina Poco Efficiente","scenario":"Un sottosistema converte energia elettrica in lavoro utile ma genera molto calore indesiderato.","question":"Qual e la lettura piu forte?","options":["Il calore e sempre irrilevante","Il bilancio mostra che una parte importante dell energia va in perdita","Conta solo la potenza di picco","Basta cambiare il colore della scocca"],"correct":1,"explanation":"Se molta energia diventa calore, l efficienza utile e limitata e il progetto va ripensato."},
    {"type":"sorting","title":"Leggere un Bilancio Termodinamico","emoji":"🧠","question":"Ordina i passaggi piu maturi per leggere un sistema termodinamico.","items":["Definire confine del sistema e flussi rilevanti","Separare energia utile, accumulo e perdite","Valutare trasformazioni e limiti di efficienza","Chiudere il margine operativo rispetto a temperatura e performance"],"explanation":"Prima scegli il sistema, poi i flussi, poi i limiti fisici e infine la performance utile."},
    {"type":"design","title":"Design Review: Conversione Energetica","brief":"Devi scegliere una strategia di conversione che massimizzi energia utile senza sforare limiti termici e di efficienza.","constraints":["Perdite non trascurabili","Temperatura massima ammessa","Duty cycle variabile","Prestazione utile da garantire"],"question":"Qual e la postura piu matura?","options":["Guardare solo l energia in ingresso","Chiudere il bilancio tra energia utile, perdite termiche e limiti di efficienza","Massimizzare la potenza sempre","Ignorare il transitorio"],"correct":1,"explanation":"Una conversione energetica seria si chiude su efficienza reale, non solo su input nominale.","tradeoffs":["Piu performance puo significare piu perdita","Il transitorio termico conta quanto il regime","Il confine del sistema va scelto bene"],"references":[{"title":"Energy conversion basics","url":"https://www.youtube.com/results?search_query=energy+conversion+basics","type":"video","source":"YouTube"}]}
  ]'::jsonb
where title = 'Termodinamica'
  and path_id = (select id from public.learning_paths where slug = 'mechanical-thinking');

update public.missions
set
  description = 'Scienza dei materiali come legame tra microstruttura, proprieta, processo e failure.',
  estimated_minutes = 13,
  xp_reward = 85,
  steps = '[
    {"type":"lesson","emoji":"🧬","title":"Il Materiale Non e Solo un Nome in Distinta","content":"Le proprieta meccaniche, termiche e chimiche di un materiale nascono da microstruttura, composizione e processo. Due pezzi della stessa lega possono comportarsi in modo diverso se lavorazione, trattamento o difetti cambiano il loro stato interno.","key_points":["Microstruttura e processo influenzano le proprieta","Il materiale va letto insieme al processo produttivo","Failure e degrado partono spesso da dettagli invisibili"],"references":[{"title":"Materials science basics","url":"https://www.youtube.com/results?search_query=materials+science+basics","type":"video","source":"YouTube"}],"visuals":[{"kind":"free-body","title":"Materiale, processo, failure","caption":"Scelta del materiale e processo definiscono il margine reale del componente."}]},
    {"type":"fill-blank","emoji":"🔬","sentence":"La microstruttura di un materiale influenza direttamente le sue ___.","options":["proprieta","icone","route dell app","query SQL"],"correct":0,"explanation":"Grana, difetti e fasi interne cambiano resistenza, duttilita, durezza e comportamento a fatica."},
    {"type":"challenge","title":"Stessa Lega, Esito Diverso","scenario":"Due componenti nominalmente uguali mostrano durate molto diverse dopo processi produttivi differenti.","question":"Qual e la lettura piu forte?","options":["Conta solo la forma CAD","Processo e microstruttura possono aver cambiato le proprieta reali","Il materiale di base non conta","Il failure e casuale"],"correct":1,"explanation":"Trattamenti, raffreddamento e difetti di processo possono spostare molto il comportamento reale."},
    {"type":"sorting","title":"Scegliere un Materiale","emoji":"🧪","question":"Ordina i passaggi piu maturi per scegliere un materiale in un progetto.","items":["Definire carichi, ambiente e vita attesa","Valutare proprieta richieste e processi compatibili","Leggere failure mode, degradazione e tolleranze","Chiudere il compromesso tra costo, massa e producibilita"],"explanation":"Prima requisiti, poi proprieta/processo, poi failure e infine costo e produzione."},
    {"type":"design","title":"Design Review: Lega o Polimero","brief":"Devi scegliere il materiale di un componente soggetto a carico ciclico, temperatura moderata e vincolo di costo.","constraints":["Vita a fatica richiesta","Costo sensibile","Produzione ripetibile","Ambiente non perfetto"],"question":"Qual e la postura piu matura?","options":["Scegliere il materiale piu rigido sempre","Valutare insieme proprieta, processo, ambiente e failure mode atteso","Guardare solo il prezzo unitario","Ignorare il degrado nel tempo"],"correct":1,"explanation":"Il materiale giusto nasce da un compromesso tra proprieta iniziali, processo e comportamento lungo la vita utile.","tradeoffs":["Piu rigidezza non significa sempre piu vita","Un materiale economico ma instabile puo costare di piu nel ciclo di vita","Il processo scelto influenza il risultato finale"],"references":[{"title":"Failure modes in materials","url":"https://www.youtube.com/results?search_query=failure+modes+in+materials","type":"video","source":"YouTube"}]}
  ]'::jsonb
where title = 'Scienza dei Materiali'
  and path_id = (select id from public.learning_paths where slug = 'mechanical-thinking');

update public.missions
set
  description = 'Cinematismi come mappe di moto, vincoli e gradi di liberta tra corpi connessi.',
  estimated_minutes = 13,
  xp_reward = 85,
  steps = '[
    {"type":"lesson","emoji":"🔩","title":"Un Cinematismo Organizza il Moto nel Sistema","content":"Un cinematismo lega corpi rigidi, giunti e vincoli per trasformare un moto in un altro. Prima di chiederti quanta forza serva, devi capire quali gradi di liberta restano, dove nasce il vincolo e come si propaga il movimento nel meccanismo.","key_points":["Il moto dipende da vincoli e giunti","I gradi di liberta vanno letti prima delle forze","Il percorso del moto e una scelta architetturale"],"references":[{"title":"Kinematics mechanisms basics","url":"https://www.youtube.com/results?search_query=kinematics+mechanisms+basics","type":"video","source":"YouTube"}],"visuals":[{"kind":"free-body","title":"Vincoli e moto","caption":"I giunti definiscono quali movimenti sono ammessi e quali no."}]},
    {"type":"fill-blank","emoji":"🧷","sentence":"Un giunto aggiunge vincoli e quindi modifica i gradi di ___.","options":["liberta","colore","compressione","deployment"],"correct":0,"explanation":"Ogni connessione meccanica limita alcuni movimenti e ne consente altri."},
    {"type":"challenge","title":"Meccanismo Imprevedibile","scenario":"Un meccanismo apparentemente semplice mostra giochi e traiettorie inattese quando aumenta la velocita operativa.","question":"Qual e la lettura piu forte?","options":["Conta solo il materiale","La catena di giunti e vincoli non e stata letta bene sul moto reale","La potenza del motore basta sempre","Il controllo software elimina ogni problema"],"correct":1,"explanation":"Se il cinematismo non e compreso, il comportamento dinamico e la precisione degradano subito."},
    {"type":"sorting","title":"Leggere un Cinematismo","emoji":"🗺️","question":"Ordina i passaggi piu maturi per leggere un meccanismo articolato.","items":["Identificare corpi, giunti e vincoli","Capire i gradi di liberta residui","Ricostruire come il moto si trasforma lungo la catena","Chiudere il compromesso tra precisione, gioco e producibilita"],"explanation":"Prima elementi e vincoli, poi mobilita, poi trasformazione del moto e infine qualita realizzativa."},
    {"type":"design","title":"Design Review: Trasmissione di Moto","brief":"Devi trasferire un moto rotativo in un movimento guidato con buona ripetibilita e poco gioco.","constraints":["Precisione richiesta","Gioco contenuto","Produzione realistica","Usura nel tempo"],"question":"Qual e la postura piu matura?","options":["Scegliere il giunto piu economico","Leggere cinematismo, gradi di liberta, gioco e percorso del moto prima della scelta finale","Aumentare sempre la velocita del motore","Ignorare l usura"],"correct":1,"explanation":"La precisione finale dipende dall architettura del cinematismo e dalla qualita dei vincoli, non solo dall attuatore.","tradeoffs":["Piu vincoli possono migliorare controllo ma peggiorare attrito","Meno gioco spesso costa piu precisione produttiva","Il moto utile va letto sull intera catena"],"references":[{"title":"Mechanism design basics","url":"https://www.youtube.com/results?search_query=mechanism+design+basics","type":"video","source":"YouTube"}]}
  ]'::jsonb
where title = 'Meccanismi e Cinematismi'
  and path_id = (select id from public.learning_paths where slug = 'mechanical-thinking');

update public.missions
set
  description = 'Selezione materiali come compromesso tra proprieta, processo, costo e failure mode atteso.',
  estimated_minutes = 13,
  xp_reward = 85,
  steps = '[
    {"type":"lesson","emoji":"🧱","title":"Scegliere un Materiale e Chiudere un Tradeoff","content":"Un materiale non si seleziona per moda o per un singolo numero in tabella. Bisogna leggere carico, ambiente, processo, costo, massa e failure mode. La scelta migliore nasce quando la proprieta giusta incontra il processo giusto per il caso d uso reale.","key_points":["Proprieta, ambiente e processo vanno letti insieme","Non esiste il materiale migliore in assoluto","Costo e failure fanno parte del requisito"],"references":[{"title":"Material selection basics","url":"https://www.youtube.com/results?search_query=material+selection+basics","type":"video","source":"YouTube"}],"visuals":[{"kind":"free-body","title":"Material selection","caption":"Carico, ambiente e processo guidano la scelta piu del nome del materiale."}]},
    {"type":"fill-blank","emoji":"📋","sentence":"Una selezione materiali matura considera sempre anche il processo di ___.","options":["fabbricazione","rendering","deploy","versioning"],"correct":0,"explanation":"Un materiale eccellente ma incompatibile col processo reale spesso non e una buona scelta."},
    {"type":"challenge","title":"Materiale Ottimo sulla Carta","scenario":"Un materiale molto performante fallisce pero nel prototipo per costi, tempi e difficolta di produzione.","question":"Qual e la lettura piu forte?","options":["Le proprieta teoriche bastano sempre","La selezione era incompleta perche mancava il vincolo di processo e costo","Conta solo la densita","Il prototipo e irrilevante"],"correct":1,"explanation":"La scelta materiale si chiude anche su fabbricabilita e catena di fornitura, non solo su numeri ideali."},
