update public.missions
set
  description = 'Fabbricazione come scelta tra processi che impongono precisione, costo, velocita e geometrie diverse.',
  estimated_minutes = 13,
  xp_reward = 85,
  steps = '[
    {"type":"lesson","emoji":"🏭","title":"Il Processo Decide Cosa e Facile, Cosa Costa, Cosa Emerge","content":"CNC, stampa 3D e lavorazione lamiera non sono solo modi diversi di fare pezzi: cambiano tolleranze, finitura, anisotropia, velocita iterativa e costo unitario. Il processo giusto dipende da geometria, volume e requisito funzionale.","key_points":["Ogni processo impone un linguaggio geometrico","Costo e velocita dipendono dal volume produttivo","La qualita finale e figlia del processo"],"references":[{"title":"Manufacturing processes overview","url":"https://www.youtube.com/results?search_query=manufacturing+processes+overview","type":"video","source":"YouTube"}],"visuals":[{"kind":"free-body","title":"Process tradeoff","caption":"Stessa funzione, processi diversi, compromessi molto diversi."}]},
    {"type":"fill-blank","emoji":"🛠️","sentence":"La stampa 3D tende a favorire complessita geometrica, mentre la CNC spesso favorisce maggiore ___.","options":["precisione locale","casualita","latenza di rete","rumore"],"correct":0,"explanation":"La CNC eccelle spesso in precisione e finitura, mentre la stampa 3D favorisce iterazione e forme complesse."},
    {"type":"challenge","title":"Pezzo Bello ma Lentissimo da Fare","scenario":"Hai scelto un processo che funziona bene sul primo prototipo, ma il tempo ciclo e troppo alto per il volume atteso.","question":"Qual e la lettura piu forte?","options":["Il processo scelto e perfetto sempre","Il volume e il costo unitario cambiano la scelta del processo ottimo","Conta solo la massa finale","Basta rifare il CAD"],"correct":1,"explanation":"Un processo eccellente per iterazione iniziale puo essere pessimo per produzione piu stabile."},
    {"type":"sorting","title":"Scegliere il Processo","emoji":"🧭","question":"Ordina i passaggi piu maturi per scegliere un processo produttivo.","items":["Capire funzione, volume e geometria del pezzo","Leggere tolleranze, finitura e proprieta richieste","Confrontare costo, lead time e rischio di processo","Chiudere il compromesso tra iterazione e produzione"],"explanation":"Prima bisogno e geometria, poi qualita richiesta, poi economia e rischio, infine strategia complessiva."},
    {"type":"design","title":"Design Review: CNC o Stampa 3D","brief":"Devi sviluppare un supporto funzionale da provare presto ma con possibile passaggio a piccola serie.","constraints":["Prototipo rapido","Possibile piccola serie","Tolleranze moderate","Costo di iterazione importante"],"question":"Qual e la postura piu matura?","options":["Scegliere il processo piu spettacolare","Valutare un processo per iterare e uno per scalare, leggendo limiti geometrici e costo","Usare sempre CNC","Usare sempre stampa 3D"],"correct":1,"explanation":"Una strategia matura considera ciclo di vita del pezzo, non solo il primo campione.","tradeoffs":["La stampa 3D accelera iterazione ma puo peggiorare proprieta e finitura","La CNC migliora precisione ma puo alzare costo e tempo iniziale","Il processo target puo essere diverso dal processo di prototipo"],"references":[{"title":"CNC vs 3D printing engineering","url":"https://www.youtube.com/results?search_query=cnc+vs+3d+printing+engineering","type":"video","source":"YouTube"}]}
