  and path_id = (select id from public.learning_paths where slug = 'materials-fabrication');

update public.missions
set
  description = 'Tolleranze e accoppiamenti come strumento per governare gioco, montaggio e prestazione.',
  estimated_minutes = 13,
  xp_reward = 85,
  steps = '[
    {"type":"lesson","emoji":"📏","title":"Ogni Accoppiamento e una Decisione di Sistema","content":"Una quota nominale non basta. Conta la banda di variazione ammessa, il processo che la produce e il comportamento del montaggio reale. Tolleranze e accoppiamenti governano gioco, interferenza, attrito, rumorosita e yield di assemblaggio.","key_points":["Il nominale non descrive il pezzo reale","Tolleranza e processo sono inseparabili","L accoppiamento influenza il comportamento finale"],"references":[{"title":"Fits and tolerances basics","url":"https://www.youtube.com/results?search_query=fits+and+tolerances+basics","type":"video","source":"YouTube"}],"visuals":[{"kind":"free-body","title":"Nominale vs reale","caption":"Il sistema vive sulla variabilita prodotta, non sul disegno perfetto."}]},
    {"type":"fill-blank","emoji":"🧩","sentence":"Un accoppiamento con troppo gioco puo peggiorare precisione, vibrazione e ___.","options":["rumorosita","versione del package","routing","compressione"],"correct":0,"explanation":"Gioco eccessivo porta spesso a errore di posizionamento, impatti e rumorosita."},
    {"type":"challenge","title":"Assemblaggio Che Non Rientra","scenario":"In linea di montaggio alcune parti entrano troppo strette e altre troppo lente pur avendo lo stesso nominale a disegno.","question":"Qual e la lettura piu forte?","options":["Le quote nominali bastano","La distribuzione delle tolleranze e il processo reale stanno dominando il comportamento","Conta solo il materiale","Serve piu lubrificante sempre"],"correct":1,"explanation":"Il comportamento di assembly dipende dalla variabilita prodotta da ogni parte, non dal solo numero nominale."},
    {"type":"sorting","title":"Chiudere un Accoppiamento","emoji":"🧠","question":"Ordina i passaggi piu maturi per definire un accoppiamento.","items":["Capire funzione e sensibilita di montaggio","Definire gioco o interferenza richiesti","Leggere capacita del processo produttivo","Chiudere il compromesso tra performance, costo e yield"],"explanation":"Prima funzione, poi finestra utile, poi capacita di processo e infine compromesso industriale."},
    {"type":"design","title":"Design Review: Albero e Boccola","brief":"Devi definire un accoppiamento tra albero e boccola con richiesta di basso gioco ma montaggio ripetibile.","constraints":["Assemblaggio ripetibile","Usura nel tempo","Costo non trascurabile","Produzione seriale"],"question":"Qual e la postura piu matura?","options":["Stringere le tolleranze al massimo","Chiudere gioco, processo, usura e yield prima di fissare le quote finali","Guardare solo il CAD nominale","Ignorare il montaggio"],"correct":1,"explanation":"Tolleranze troppo aggressive senza capacita di processo reale possono distruggere costi e yield.","tradeoffs":["Meno gioco migliora precisione ma complica montaggio","Piu tolleranza abbassa costo ma puo peggiorare rumore e usura","Il processo reale decide cosa e stabile produrre"],"references":[{"title":"Tolerance stack-up basics","url":"https://www.youtube.com/results?search_query=tolerance+stackup+basics","type":"video","source":"YouTube"}]}
