  steps = '[
    {"type":"lesson","emoji":"🧰","title":"Un Progetto Forte Riduce Difficolta Inutili","content":"DFM significa progettare un pezzo pensando gia a come verra fabbricato, montato, misurato e mantenuto. Una geometria elegante ma ostile al processo genera costi, scarti e ritardi. Il progetto migliore spesso e quello che semplifica la catena intera.","key_points":["Il pezzo va pensato nel processo reale","Semplicita produttiva e un vantaggio tecnico","DFM riduce costo e rischio"],"references":[{"title":"Design for manufacturing basics","url":"https://www.youtube.com/results?search_query=design+for+manufacturing+basics","type":"video","source":"YouTube"}],"visuals":[{"kind":"free-body","title":"From CAD to factory","caption":"Il valore del design si misura anche nella facilita di produrlo."}]},
    {"type":"fill-blank","emoji":"🏷️","sentence":"Un principio base del DFM e ridurre feature inutilmente ___.","options":["complesse","luminose","colorate","interattive"],"correct":0,"explanation":"Feature complesse e poco funzionali fanno esplodere costo e variabilita senza portare valore."},
    {"type":"challenge","title":"Pezzo Bellissimo, Yield Disastroso","scenario":"Un componente ha superato il test funzionale ma in produzione mostra scarti elevati e tempi ciclo troppo lunghi.","question":"Qual e la lettura piu forte?","options":["Il design e gia buono","Il progetto non ha chiuso bene il lato produttivo del problema","Conta solo la qualita del fornitore","Serve piu marketing"],"correct":1,"explanation":"Se il design ignora il processo reale, la funzione da sola non basta a renderlo un buon prodotto."},
    {"type":"sorting","title":"Leggere il DFM","emoji":"🧭","question":"Ordina i passaggi piu maturi per applicare DFM a un componente.","items":["Capire funzione e processo target","Individuare feature critiche o costose da produrre","Semplificare geometria, lavorazioni e montaggio","Chiudere il compromesso tra performance, costo e yield"],"explanation":"Prima funzione e processo, poi criticita, poi semplificazione e infine compromesso finale."},
    {"type":"design","title":"Design Review: Supporto da Industrializzare","brief":"Devi portare un supporto da prototipo rapido a piccola serie senza perdere funzione ma riducendo scarti e tempi.","constraints":["Prestazione da mantenere","Yield basso attuale","Tempi ciclo alti","Assemblaggio da semplificare"],"question":"Qual e la postura piu matura?","options":["Lasciare tutto invariato","Rileggere il design sulle difficolta reali di processo, montaggio e misura","Aggiungere tolleranze piu strette ovunque","Ignorare il fornitore"],"correct":1,"explanation":"DFM forte significa tradurre la funzione in un pezzo realmente producibile con margine.","tradeoffs":["Semplificare il pezzo puo cambiare leggermente performance ma migliorare molto il sistema","Meno feature critiche spesso significano piu yield","Misurabilita e montaggio vanno pensati presto"],"references":[{"title":"DFM examples engineering","url":"https://www.youtube.com/results?search_query=dfm+examples+engineering","type":"video","source":"YouTube"}]}
