update public.missions
set
  description = 'FEA come strumento per leggere dove si concentra lo sforzo e validare ipotesi, non come risposta automatica.',
  estimated_minutes = 13,
  xp_reward = 85,
  steps = '[
    {"type":"lesson","emoji":"🧮","title":"La Simulazione e Forte Solo Se la Domanda e Giusta","content":"Una FEA non sostituisce il ragionamento meccanico. Funziona bene quando il modello rappresenta carichi, vincoli e materiale in modo coerente con il caso reale. Il valore sta nel capire hotspot, deformazioni e sensitivita, non nel color map piu bello.","key_points":["La qualita del risultato dipende dal modello","Vincoli e mesh guidano l attendibilita","La simulazione serve a leggere, non a decorare"],"references":[{"title":"Finite element analysis basics","url":"https://www.youtube.com/results?search_query=finite+element+analysis+basics","type":"video","source":"YouTube"}],"visuals":[{"kind":"free-body","title":"Model assumptions first","caption":"La simulazione e utile solo se carichi e vincoli rappresentano il caso reale."}]},
    {"type":"fill-blank","emoji":"📐","sentence":"In FEA, vincoli non realistici possono produrre risultati molto ___.","options":["fuorvianti","ottimali","stabili sempre","neutri"],"correct":0,"explanation":"Se blocchi o carichi il modello in modo scorretto, anche la mappa finale perde valore."},
    {"type":"challenge","title":"Color Map Convincente, Pezzo Rotto","scenario":"La simulazione sembrava rassicurante, ma il prototipo ha ceduto vicino a un foro non modellato bene.","question":"Qual e la lettura piu forte?","options":["La FEA e inutile sempre","Le assunzioni del modello non catturavano il punto critico reale","Conta solo la mesh fine","Il prototipo e sbagliato per definizione"],"correct":1,"explanation":"Una simulazione forte richiede dettagli e condizioni coerenti col failure reale atteso."},
    {"type":"sorting","title":"Usare Bene la FEA","emoji":"🧠","question":"Ordina i passaggi piu maturi per usare la simulazione strutturale.","items":["Definire la domanda ingegneristica e il caso di carico","Costruire modello, vincoli e mesh coerenti","Leggere hotspot e sensitivita dei risultati","Chiudere il loop con verifica fisica o semplificazioni analitiche"],"explanation":"Prima domanda, poi modello, poi lettura e infine confronto con realta o stime indipendenti."},
    {"type":"design","title":"Design Review: Quando Simulare","brief":"Stai alleggerendo una struttura e devi decidere quanto affidarti alla FEA in una fase ancora rapida di progetto.","constraints":["Tempo limitato","Geometria non definitiva","Carichi principali noti","Serve evitare errori grossolani"],"question":"Qual e la postura piu matura?","options":["Fare solo FEA dettagliatissima","Usare FEA per hotspot e tradeoff, ma chiudere il loop con ragionamento e test mirati","Saltare ogni simulazione","Guardare solo la deformata estetica"],"correct":1,"explanation":"La simulazione rende molto quando e usata come strumento per ridurre rischio, non come sostituto del pensiero tecnico.","tradeoffs":["Piu dettaglio puo costare tempo senza aumentare valore all inizio","Una stima analitica puo verificare la direzione del risultato","Il modello deve evolvere col progetto"],"references":[{"title":"FEA workflow engineering","url":"https://www.youtube.com/results?search_query=fea+workflow+engineering","type":"video","source":"YouTube"}]}
  ]'::jsonb
where title = 'Analisi agli Elementi Finiti (FEA)'
  and path_id = (select id from public.learning_paths where slug = 'materials-fabrication');

update public.missions
set
  description = 'Materiali avanzati e compositi come strumenti potenti ma sensibili a processo, anisotropia e failure specifici.',
  estimated_minutes = 13,
  xp_reward = 85,
  steps = '[
    {"type":"lesson","emoji":"🧵","title":"I Compositi Sono Potenti ma Non Perdono Errori di Processo","content":"Materiali compositi e avanzati possono offrire ottimo rapporto rigidezza-massa, ma introducono anisotropia, interfacce, sensibilita a difetti e processi delicati. Vanno scelti quando il beneficio di sistema e reale e la catena produttiva regge.","key_points":["Le proprieta dipendono dalla direzione","Processo e qualita interna sono cruciali","Il vantaggio va chiuso sul sistema completo"],"references":[{"title":"Composite materials basics","url":"https://www.youtube.com/results?search_query=composite+materials+basics","type":"video","source":"YouTube"}],"visuals":[{"kind":"free-body","title":"Advanced material tradeoff","caption":"Prestazioni alte richiedono processo e verifica piu disciplinati."}]},
