update public.missions
set
  description = 'Metrologia e controllo qualita come strumenti per capire se il pezzo reale rispetta davvero il progetto.',
  estimated_minutes = 13,
  xp_reward = 85,
  steps = '[
    {"type":"lesson","emoji":"📡","title":"Se Non Misuri Bene, Non Sai Cosa Stai Costruendo","content":"Il controllo qualita non e un passaggio amministrativo. Serve a collegare disegno, processo e pezzo reale. Misurare significa sapere quali dimensioni, proprieta o difetti contano davvero e con quale incertezza li stai leggendo.","key_points":["Misura e qualita chiudono il loop col processo","Non tutte le quote hanno lo stesso valore funzionale","L incertezza di misura conta"],"references":[{"title":"Metrology basics engineering","url":"https://www.youtube.com/results?search_query=metrology+basics+engineering","type":"video","source":"YouTube"}],"visuals":[{"kind":"free-body","title":"Measure what matters","caption":"La qualita utile nasce dalle caratteristiche davvero critiche per la funzione."}]},
    {"type":"fill-blank","emoji":"📐","sentence":"Una misura utile richiede sapere cosa misurare e con quale ___.","options":["accuratezza","colore","animazione","plugin"],"correct":0,"explanation":"Lo strumento e il metodo devono essere adatti alla caratteristica da controllare."},
    {"type":"challenge","title":"Pezzi Entro Disegno, Sistema Fuori Spec","scenario":"Ogni componente sembra rientrare nelle quote principali, ma il montaggio finale continua a dare problemi di precisione.","question":"Qual e la lettura piu forte?","options":["Le misure non servono","Probabilmente stai misurando le cose sbagliate o ignorando stack-up e variabilita funzionale","Conta solo il materiale","La linea e sfortunata"],"correct":1,"explanation":"La qualita utile richiede misure centrate sulle caratteristiche critiche del sistema, non solo sulle quote facili."},
    {"type":"sorting","title":"Impostare un Controllo Qualita","emoji":"🧭","question":"Ordina i passaggi piu maturi per impostare un piano di misura.","items":["Capire quali caratteristiche guidano la funzione","Scegliere strumenti e metodo di misura adeguati","Leggere variabilita e correlazione col processo","Chiudere il loop correttivo su disegno o produzione"],"explanation":"Prima caratteristiche critiche, poi metodo di misura, poi variabilita e infine azione correttiva."},
    {"type":"design","title":"Design Review: Cosa Misurare Davvero","brief":"Devi definire un piano di controllo per un sottoassieme che soffre giochi e disallineamenti in montaggio.","constraints":["Tempo misura limitato","Non tutto puo essere controllato","Problema funzionale gia osservato","Serve feedback al processo"],"question":"Qual e la postura piu matura?","options":["Misurare tutto senza priorita","Selezionare le caratteristiche realmente critiche e costruire un loop di feedback col processo","Misurare solo a campione casuale","Ignorare il montaggio"],"correct":1,"explanation":"La metrologia forte misura cio che spiega il comportamento del sistema e aiuta a correggerlo.","tradeoffs":["Piu misure non significano piu valore se non sono le misure giuste","Uno strumento preciso non basta senza un buon piano","La qualita si chiude tra misura e azione"],"references":[{"title":"Measurement system analysis basics","url":"https://www.youtube.com/results?search_query=measurement+system+analysis+basics","type":"video","source":"YouTube"}]}
  ]'::jsonb
where title = 'Controllo Qualita e Metrologia'
  and path_id = (select id from public.learning_paths where slug = 'materials-fabrication');

update public.missions
set
  description = 'Capstone di fabbricazione come chiusura integrata tra materiale, processo, tolleranze, test e produzione.',
  estimated_minutes = 15,
  xp_reward = 100,
  steps = '[
    {"type":"lesson","emoji":"🧠","title":"Un Buon Progetto di Fabbricazione Tiene Insieme Tutto","content":"Nel capstone devi leggere il sistema completo: scelta materiale, processo, tolleranze, giunzioni, verifica e sequenza di build. Il progetto non vale se una singola decisione locale distrugge costo, yield o manutenzione del prodotto finale.","key_points":["Il valore e nell integrazione delle decisioni","Materiale e processo non possono essere separati","Qualita e test chiudono il progetto"],"references":[{"title":"Product realization workflow","url":"https://www.youtube.com/results?search_query=product+realization+workflow","type":"video","source":"YouTube"}],"visuals":[{"kind":"free-body","title":"Integrated fabrication thinking","caption":"Il capstone richiede una lettura integrata di progetto, processo e verifica."}]},
    {"type":"sorting","title":"Roadmap di Industrializzazione","emoji":"🗺️","question":"Ordina le fasi piu mature per portare un componente dal concept alla produzione iniziale.","items":["Definire funzione, carichi e vincoli del componente","Chiudere materiale, processo e tolleranze target","Validare con prototipo e misure critiche","Stabilire piano di assemblaggio, controllo qualita e rilascio"],"explanation":"Prima il requisito, poi le scelte tecniche, poi la verifica e infine il rilascio produttivo."},
    {"type":"challenge","title":"Progetto Ottimo ma Non Scalabile","scenario":"Il prototipo funziona, ma la soluzione scelta dipende da lavorazioni lente, controlli manuali e giunzioni difficili da ripetere.","question":"Qual e la lettura piu forte?","options":["Il progetto e comunque chiuso","La soluzione non ha ancora chiuso industrializzazione e rischio di produzione","Conta solo il test funzionale","Basta cambiare fornitore"],"correct":1,"explanation":"Un progetto di fabbricazione e completo solo quando regge anche nella fase di build e qualita."},
    {"type":"design","title":"Capstone Review: Build Strategy","brief":"Devi proporre la strategia di realizzazione di un sottosistema fisico bilanciando performance, costo, tempi e robustezza di produzione.","constraints":["Prestazione reale da garantire","Budget finito","Yield importante","Test e misura disponibili ma non illimitati"],"question":"Qual e la postura piu matura?","options":["Scegliere il materiale piu forte e procedere","Chiudere un architettura coerente tra materiale, processo, tolleranze, assemblaggio e verifica","Massimizzare solo la performance tecnica","Ignorare la metrologia"],"correct":1,"explanation":"Il capstone valuta se sai integrare le scelte e non solo ottimizzare una variabile.","tradeoffs":["Piu performance puo alzare rischio industriale","Una scelta robusta di processo puo valere piu di un materiale piu spinto","Verifica e qualita sono parte dell architettura"],"references":[{"title":"DFX and production readiness","url":"https://www.youtube.com/results?search_query=dfx+production+readiness","type":"video","source":"YouTube"}]}
  ]'::jsonb
